'use strict';

/**
 * osdm-conformance.js — an answer of the simulator checked against the OSDM
 * response schema of the provider's version (#833). Test helper.
 *
 * The schemas are fixtures/osdm-response-schemas.json, generated by
 * Oscar_Server/scripts/generate-osdm-response-schemas.js, in the compact form
 * of the collection's request check (library-bruno/osdmRequestSchema.js,
 * #736): the walk below is that check's, applied to answers. Member names and
 * paths only, never values.
 */

const SCHEMAS = require('./fixtures/osdm-response-schemas.json');

const MAX_DEPTH = 64;

function pathSegments(url) {
  const noQuery = String(url || '').split(/[?#]/)[0];
  return noQuery.replace(/^[a-z][a-z0-9+.-]*:\/\/[^/]+/i, '').split('/').filter(Boolean);
}

// The operation a request went to: the longest template its path ends with.
function operationFor(version, method, url, status) {
  const ops = SCHEMAS.versions[version]?.operations || [];
  const segments = pathSegments(url);
  const m = String(method || '').toUpperCase();
  let found = null;
  for (const op of ops) {
    if (op.method !== m || op.status !== status) continue;
    const parts = op.path.split('/').filter(Boolean);
    if (parts.length > segments.length) continue;
    const tail = segments.slice(segments.length - parts.length);
    if (!parts.every((p, i) => p.startsWith('{') || p === tail[i])) continue;
    if (!found || parts.length > found.path.split('/').filter(Boolean).length) found = op;
  }
  return found;
}

function typeOf(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  if (typeof value === 'number' && Number.isInteger(value)) return 'integer';
  return typeof value;
}

function typeFits(value, schema) {
  if (value === null) return schema.nullable === true;
  if (!schema.type) return true;
  const t = typeOf(value);
  if (schema.type === 'number') return t === 'number' || t === 'integer';
  return t === schema.type;
}

function checkObject(value, schema, ctx, path) {
  const missing = (schema.required || []).filter((name) => value[name] === undefined);
  if (missing.length) ctx.issues.push(`${path || '(body)'}: missing ${missing.join(', ')}`);
  const props = schema.properties || {};
  for (const name of Object.keys(value)) {
    const child = path ? `${path}.${name}` : name;
    if (props[name]) visit(value[name], props[name], ctx, child);
    else if (schema.additionalProperties === false) ctx.issues.push(`${child}: not a member of ${ctx.owner}`);
    else if (schema.additionalProperties) visit(value[name], schema.additionalProperties, ctx, child);
  }
}

function checkArray(value, schema, ctx, path) {
  if (typeof schema.minItems === 'number' && value.length < schema.minItems) ctx.issues.push(`${path}: at least ${schema.minItems} item(s)`);
  if (typeof schema.maxItems === 'number' && value.length > schema.maxItems) ctx.issues.push(`${path}: at most ${schema.maxItems} item(s)`);
  if (schema.items) value.forEach((item, i) => visit(item, schema.items, ctx, `${path}[${i}]`));
}

function checkString(value, schema, ctx, path) {
  if (schema.enum && !schema.enum.includes(value)) ctx.issues.push(`${path}: "${value}" is not one of ${schema.enum.slice(0, 8).join(', ')}`);
  if (typeof schema.minLength === 'number' && value.length < schema.minLength) ctx.issues.push(`${path}: shorter than ${schema.minLength}`);
  if (typeof schema.maxLength === 'number' && value.length > schema.maxLength) ctx.issues.push(`${path}: longer than ${schema.maxLength}`);
}

function checkAlternatives(value, schema, ctx, path) {
  let best = null;
  for (const alt of schema.anyOf) {
    const trial = { schemas: ctx.schemas, owner: ctx.owner, depth: ctx.depth, issues: [] };
    visit(value, alt, trial, path);
    if (!trial.issues.length) return;
    if (!best || trial.issues.length < best.length) best = trial.issues;
  }
  ctx.issues.push(...best);
}

function subtypeNamed(value, schema, ctx) {
  const d = schema.discriminator;
  if (!d || typeOf(value) !== 'object' || typeof value[d.propertyName] !== 'string') return null;
  const target = d.mapping?.[value[d.propertyName]] || value[d.propertyName];
  if (target === ctx.owner) return null;
  return ctx.schemas[target] ? target : '';
}

function visitRef(value, name, ctx, path) {
  visit(value, ctx.schemas[name], { schemas: ctx.schemas, owner: name, depth: ctx.depth + 1, issues: ctx.issues }, path);
}

function visit(value, schema, ctx, path) {
  if (!schema || ctx.depth > MAX_DEPTH) return;
  if (schema.$ref) { visitRef(value, schema.$ref, ctx, path); return; }
  const subtype = subtypeNamed(value, schema, ctx);
  if (subtype) { visitRef(value, subtype, ctx, path); return; }
  if (subtype === '') { ctx.issues.push(`${path ? path + '.' : ''}${schema.discriminator.propertyName}: names no type of ${ctx.owner}`); return; }
  if (schema.anyOf) { checkAlternatives(value, schema, ctx, path); return; }
  if (!typeFits(value, schema)) { ctx.issues.push(`${path || '(body)'}: expected ${schema.type}, got ${typeOf(value)}`); return; }
  if (value === null) return;
  const t = typeOf(value);
  if (t === 'object') checkObject(value, schema, ctx, path);
  else if (t === 'array') checkArray(value, schema, ctx, path);
  else if (t === 'string') checkString(value, schema, ctx, path);
}

/**
 * The issues of one answer: [] when it conforms, null when OSDM defines no
 * JSON body for that operation and status (nothing to check).
 */
function responseIssues(version, method, url, status, body) {
  const op = operationFor(version, method, url, status);
  if (!op) return null;
  const ctx = { schemas: SCHEMAS.versions[version].schemas, owner: op.path, depth: 0, issues: [] };
  visit(body, op.schema, ctx, '');
  return ctx.issues;
}

module.exports = { responseIssues, operationFor, VERSIONS: Object.keys(SCHEMAS.versions) };
